-- Jimvolt PostgreSQL schema (final state). Every statement is idempotent, so it is safe to run
-- on every startup. Existing tables and rows are never dropped or rewritten.
--
-- Notes on the MySQL -> PostgreSQL translation:
--   * AUTO_INCREMENT      -> BIGINT GENERATED BY DEFAULT AS IDENTITY
--   * ENUM                -> TEXT with a CHECK constraint (easy to extend later)
--   * case-insensitive collation -> CITEXT for emails, usernames, slugs and names
--   * ON UPDATE CURRENT_TIMESTAMP -> the set_updated_at() trigger below
--   * FULLTEXT index      -> GIN index over a to_tsvector expression

CREATE EXTENSION IF NOT EXISTS citext;

CREATE OR REPLACE FUNCTION set_updated_at() RETURNS trigger AS $$
BEGIN
  NEW.updated_at = CURRENT_TIMESTAMP;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TABLE IF NOT EXISTS users (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  full_name VARCHAR(120) NOT NULL,
  email CITEXT NOT NULL,
  phone VARCHAR(32) NULL,
  password VARCHAR(255) NOT NULL,
  token_version INTEGER NOT NULL DEFAULT 0,
  role TEXT NOT NULL DEFAULT 'user',
  profile_image VARCHAR(2048) NULL,
  account_status TEXT NOT NULL DEFAULT 'active',
  is_verified BOOLEAN NOT NULL DEFAULT FALSE,
  password_reset_token VARCHAR(255) NULL,
  password_reset_expires_at TIMESTAMPTZ NULL,
  pending_email CITEXT NULL,
  email_verification_token VARCHAR(255) NULL,
  email_verification_expires_at TIMESTAMPTZ NULL,
  username CITEXT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT uq_users_email UNIQUE (email),
  CONSTRAINT uq_users_phone UNIQUE (phone),
  CONSTRAINT uq_users_username UNIQUE (username),
  CONSTRAINT chk_users_role CHECK (role IN ('user', 'admin', 'super_admin')),
  CONSTRAINT chk_users_status CHECK (account_status IN ('active', 'suspended'))
);
CREATE INDEX IF NOT EXISTS idx_users_status ON users (account_status);

CREATE TABLE IF NOT EXISTS categories (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name CITEXT NOT NULL,
  slug CITEXT NOT NULL,
  description TEXT NULL,
  image VARCHAR(2048) NULL,
  is_active BOOLEAN NOT NULL DEFAULT TRUE,
  display_order INTEGER NOT NULL DEFAULT 0,
  created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT uq_categories_name UNIQUE (name),
  CONSTRAINT uq_categories_slug UNIQUE (slug)
);

CREATE TABLE IF NOT EXISTS advertisements (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id BIGINT NOT NULL,
  category_id BIGINT NOT NULL,
  title VARCHAR(180) NOT NULL,
  brand VARCHAR(120) NULL,
  specifications TEXT NULL,
  slug CITEXT NOT NULL,
  description TEXT NOT NULL,
  price NUMERIC(13, 2) NOT NULL,
  condition_type TEXT NOT NULL,
  state VARCHAR(100) NOT NULL,
  city VARCHAR(120) NOT NULL,
  phone VARCHAR(32) NOT NULL,
  whatsapp VARCHAR(32) NULL,
  status TEXT NOT NULL DEFAULT 'pending',
  moderation_note VARCHAR(1000) NULL,
  approved_at TIMESTAMPTZ NULL,
  views BIGINT NOT NULL DEFAULT 0,
  is_featured BOOLEAN NOT NULL DEFAULT FALSE,
  created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT uq_advertisements_slug UNIQUE (slug),
  CONSTRAINT fk_ads_user FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE,
  CONSTRAINT fk_ads_category FOREIGN KEY (category_id) REFERENCES categories (id) ON DELETE RESTRICT,
  CONSTRAINT chk_ads_price CHECK (price >= 0),
  CONSTRAINT chk_ads_condition CHECK (condition_type IN ('new', 'used')),
  CONSTRAINT chk_ads_status CHECK (status IN ('pending', 'approved', 'rejected', 'paused', 'suspended', 'changes_requested', 'sold', 'expired'))
);
CREATE INDEX IF NOT EXISTS idx_ads_public_newest ON advertisements (status, created_at);
CREATE INDEX IF NOT EXISTS idx_ads_user ON advertisements (user_id, status);
CREATE INDEX IF NOT EXISTS idx_ads_category ON advertisements (category_id, status);
CREATE INDEX IF NOT EXISTS idx_ads_location ON advertisements (state, city, status);
CREATE INDEX IF NOT EXISTS idx_ads_price ON advertisements (price, status);
CREATE INDEX IF NOT EXISTS idx_ads_featured ON advertisements (is_featured, status);
CREATE INDEX IF NOT EXISTS idx_ads_condition_status ON advertisements (condition_type, status);
CREATE INDEX IF NOT EXISTS idx_ads_city_status ON advertisements (city, status);
CREATE INDEX IF NOT EXISTS ft_ads_search ON advertisements USING GIN (
  to_tsvector('simple', coalesce(title, '') || ' ' || coalesce(description, '') || ' ' || coalesce(brand, '') || ' ' || coalesce(specifications, ''))
);

CREATE TABLE IF NOT EXISTS product_images (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  advertisement_id BIGINT NOT NULL,
  image_url VARCHAR(2048) NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT fk_product_images_ad FOREIGN KEY (advertisement_id) REFERENCES advertisements (id) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS idx_product_images_ad ON product_images (advertisement_id);

CREATE TABLE IF NOT EXISTS favourites (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id BIGINT NOT NULL,
  advertisement_id BIGINT NULL,
  saved_title VARCHAR(180) NULL,
  saved_price NUMERIC(13, 2) NULL,
  saved_condition_type TEXT NULL,
  saved_state VARCHAR(100) NULL,
  saved_city VARCHAR(120) NULL,
  saved_image VARCHAR(2048) NULL,
  saved_seller_name VARCHAR(120) NULL,
  saved_category_id BIGINT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT uq_favourites_user_ad UNIQUE (user_id, advertisement_id),
  CONSTRAINT fk_favourites_user FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE,
  CONSTRAINT fk_favourites_ad FOREIGN KEY (advertisement_id) REFERENCES advertisements (id) ON DELETE SET NULL,
  CONSTRAINT chk_favourites_condition CHECK (saved_condition_type IS NULL OR saved_condition_type IN ('new', 'used'))
);
CREATE INDEX IF NOT EXISTS idx_favourites_ad ON favourites (advertisement_id, user_id);

CREATE TABLE IF NOT EXISTS recently_viewed (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id BIGINT NOT NULL,
  advertisement_id BIGINT NOT NULL,
  viewed_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT uq_recently_viewed_user_ad UNIQUE (user_id, advertisement_id),
  CONSTRAINT fk_recently_viewed_user FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE,
  CONSTRAINT fk_recently_viewed_ad FOREIGN KEY (advertisement_id) REFERENCES advertisements (id) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS idx_recently_viewed_user_date ON recently_viewed (user_id, viewed_at);

CREATE TABLE IF NOT EXISTS price_history (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  advertisement_id BIGINT NOT NULL,
  old_price NUMERIC(13, 2) NOT NULL,
  new_price NUMERIC(13, 2) NOT NULL,
  changed_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT fk_price_history_ad FOREIGN KEY (advertisement_id) REFERENCES advertisements (id) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS idx_price_history_ad_date ON price_history (advertisement_id, changed_at);

CREATE TABLE IF NOT EXISTS wishlist_preferences (
  user_id BIGINT PRIMARY KEY,
  notify_price_drops BOOLEAN NOT NULL DEFAULT TRUE,
  created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT fk_wishlist_preferences_user FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS conversations (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  buyer_id BIGINT NOT NULL,
  seller_id BIGINT NOT NULL,
  advertisement_id BIGINT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT fk_conversation_buyer FOREIGN KEY (buyer_id) REFERENCES users (id) ON DELETE CASCADE,
  CONSTRAINT fk_conversation_seller FOREIGN KEY (seller_id) REFERENCES users (id) ON DELETE CASCADE,
  CONSTRAINT fk_conversation_ad FOREIGN KEY (advertisement_id) REFERENCES advertisements (id) ON DELETE SET NULL,
  CONSTRAINT chk_conversation_different_users CHECK (buyer_id <> seller_id)
);
-- MySQL treats NULL advertisement_id values as distinct in a unique key, and so does this index.
CREATE UNIQUE INDEX IF NOT EXISTS uq_conversation_buyer_seller_ad ON conversations (buyer_id, seller_id, advertisement_id);
CREATE INDEX IF NOT EXISTS idx_conversation_seller_updated ON conversations (seller_id, updated_at);
CREATE INDEX IF NOT EXISTS idx_conversation_buyer_updated ON conversations (buyer_id, updated_at);

CREATE TABLE IF NOT EXISTS conversation_participants (
  conversation_id BIGINT NOT NULL,
  user_id BIGINT NOT NULL,
  last_read_at TIMESTAMPTZ NULL,
  is_archived BOOLEAN NOT NULL DEFAULT FALSE,
  created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (conversation_id, user_id),
  CONSTRAINT fk_conversation_participant_conversation FOREIGN KEY (conversation_id) REFERENCES conversations (id) ON DELETE CASCADE,
  CONSTRAINT fk_conversation_participant_user FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS idx_conversation_participant_inbox ON conversation_participants (user_id, is_archived, updated_at);

CREATE TABLE IF NOT EXISTS messages (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  conversation_id BIGINT NULL,
  sender_id BIGINT NOT NULL,
  receiver_id BIGINT NOT NULL,
  advertisement_id BIGINT NULL,
  message TEXT NOT NULL,
  message_type TEXT NOT NULL DEFAULT 'text',
  message_content TEXT NULL,
  attachment_url VARCHAR(2048) NULL,
  attachment_public_id VARCHAR(255) NULL,
  delivered_at TIMESTAMPTZ NULL,
  is_read BOOLEAN NOT NULL DEFAULT FALSE,
  created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT fk_messages_conversation FOREIGN KEY (conversation_id) REFERENCES conversations (id) ON DELETE CASCADE,
  CONSTRAINT fk_messages_sender FOREIGN KEY (sender_id) REFERENCES users (id) ON DELETE CASCADE,
  CONSTRAINT fk_messages_receiver FOREIGN KEY (receiver_id) REFERENCES users (id) ON DELETE CASCADE,
  CONSTRAINT fk_messages_ad FOREIGN KEY (advertisement_id) REFERENCES advertisements (id) ON DELETE SET NULL,
  CONSTRAINT chk_messages_type CHECK (message_type IN ('text', 'image'))
);
CREATE INDEX IF NOT EXISTS idx_messages_conversation_time ON messages (conversation_id, created_at, id);
CREATE INDEX IF NOT EXISTS idx_messages_inbox ON messages (receiver_id, is_read, created_at);
CREATE INDEX IF NOT EXISTS idx_messages_sender ON messages (sender_id, created_at);
CREATE INDEX IF NOT EXISTS idx_messages_ad ON messages (advertisement_id);

CREATE TABLE IF NOT EXISTS seller_profiles (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id BIGINT NOT NULL,
  business_name VARCHAR(160) NOT NULL,
  slug CITEXT NOT NULL,
  public_slug CITEXT NULL,
  logo_url VARCHAR(2048) NULL,
  description TEXT NULL,
  email VARCHAR(254) NULL,
  phone VARCHAR(32) NULL,
  whatsapp VARCHAR(32) NULL,
  website_url VARCHAR(2048) NULL,
  address VARCHAR(255) NULL,
  state VARCHAR(100) NULL,
  city VARCHAR(120) NULL,
  years_in_business SMALLINT NULL,
  operating_hours VARCHAR(500) NULL,
  category_id BIGINT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT uq_seller_profiles_user UNIQUE (user_id),
  CONSTRAINT uq_seller_profiles_slug UNIQUE (slug),
  CONSTRAINT uq_seller_profiles_public_slug UNIQUE (public_slug),
  CONSTRAINT fk_seller_profiles_user FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE,
  CONSTRAINT fk_seller_profiles_category FOREIGN KEY (category_id) REFERENCES categories (id) ON DELETE SET NULL
);
CREATE INDEX IF NOT EXISTS idx_seller_profiles_category ON seller_profiles (category_id);

CREATE TABLE IF NOT EXISTS seller_slug_history (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id BIGINT NOT NULL,
  old_slug CITEXT NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT uq_slug_history_slug UNIQUE (old_slug),
  CONSTRAINT fk_slug_history_user FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS idx_slug_history_user ON seller_slug_history (user_id);

CREATE TABLE IF NOT EXISTS seller_verifications (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id BIGINT NOT NULL,
  verification_type TEXT NOT NULL,
  business_name VARCHAR(160) NULL,
  registration_number VARCHAR(100) NULL,
  business_address VARCHAR(255) NOT NULL,
  business_phone VARCHAR(32) NOT NULL,
  business_owner VARCHAR(120) NULL,
  business_email VARCHAR(254) NULL,
  whatsapp VARCHAR(32) NULL,
  state VARCHAR(100) NULL,
  city VARCHAR(120) NULL,
  business_description TEXT NULL,
  website VARCHAR(2048) NULL,
  business_category_id BIGINT NULL,
  cac_document_path VARCHAR(255) NULL,
  identity_document_path VARCHAR(255) NULL,
  additional_document_path VARCHAR(255) NULL,
  document_path VARCHAR(255) NOT NULL,
  status TEXT NOT NULL DEFAULT 'pending',
  admin_notes VARCHAR(1000) NULL,
  rejection_reason VARCHAR(1000) NULL,
  reviewed_by BIGINT NULL,
  submitted_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
  reviewed_at TIMESTAMPTZ NULL,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT fk_seller_verifications_user FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE,
  CONSTRAINT fk_seller_verifications_category FOREIGN KEY (business_category_id) REFERENCES categories (id) ON DELETE SET NULL,
  CONSTRAINT fk_seller_verifications_reviewer FOREIGN KEY (reviewed_by) REFERENCES users (id) ON DELETE SET NULL,
  CONSTRAINT chk_seller_verifications_type CHECK (verification_type IN ('individual', 'registered_business', 'renewable_energy_company')),
  CONSTRAINT chk_seller_verifications_status CHECK (status IN ('pending', 'verified', 'rejected', 'information_requested', 'revoked'))
);
CREATE INDEX IF NOT EXISTS idx_seller_verifications_user ON seller_verifications (user_id, submitted_at);
CREATE INDEX IF NOT EXISTS idx_seller_verifications_status ON seller_verifications (status, submitted_at);
CREATE INDEX IF NOT EXISTS idx_seller_verifications_category ON seller_verifications (business_category_id);

CREATE TABLE IF NOT EXISTS advertisement_analytics (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  advertisement_id BIGINT NOT NULL,
  event_type TEXT NOT NULL,
  occurred_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT fk_ad_analytics_ad FOREIGN KEY (advertisement_id) REFERENCES advertisements (id) ON DELETE CASCADE,
  CONSTRAINT chk_ad_analytics_event CHECK (event_type IN ('view'))
);
CREATE INDEX IF NOT EXISTS idx_ad_analytics_ad_time ON advertisement_analytics (advertisement_id, occurred_at);
CREATE INDEX IF NOT EXISTS idx_ad_analytics_time ON advertisement_analytics (occurred_at);

CREATE TABLE IF NOT EXISTS notifications (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id BIGINT NOT NULL,
  type VARCHAR(50) NOT NULL,
  title VARCHAR(160) NOT NULL,
  body VARCHAR(500) NOT NULL,
  related_advertisement_id BIGINT NULL,
  dedupe_key VARCHAR(191) NULL,
  is_read BOOLEAN NOT NULL DEFAULT FALSE,
  created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT uq_notifications_user_dedupe UNIQUE (user_id, dedupe_key),
  CONSTRAINT fk_notifications_user FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE,
  CONSTRAINT fk_notifications_ad FOREIGN KEY (related_advertisement_id) REFERENCES advertisements (id) ON DELETE SET NULL
);
CREATE INDEX IF NOT EXISTS idx_notifications_user ON notifications (user_id, is_read, created_at);

CREATE TABLE IF NOT EXISTS admin_audit_logs (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  administrator_id BIGINT NULL,
  action VARCHAR(80) NOT NULL,
  entity_type VARCHAR(40) NOT NULL,
  entity_id BIGINT NULL,
  previous_value JSONB NULL,
  new_value JSONB NULL,
  ip_address VARCHAR(45) NULL,
  user_agent VARCHAR(500) NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT fk_admin_audit_actor FOREIGN KEY (administrator_id) REFERENCES users (id) ON DELETE SET NULL
);
CREATE INDEX IF NOT EXISTS idx_admin_audit_created ON admin_audit_logs (created_at);
CREATE INDEX IF NOT EXISTS idx_admin_audit_actor ON admin_audit_logs (administrator_id, created_at);
CREATE INDEX IF NOT EXISTS idx_admin_audit_entity ON admin_audit_logs (entity_type, entity_id, created_at);

CREATE TABLE IF NOT EXISTS reports (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  reporter_id BIGINT NOT NULL,
  advertisement_id BIGINT NULL,
  seller_id BIGINT NULL,
  conversation_id BIGINT NULL,
  message_id BIGINT NULL,
  category TEXT NOT NULL,
  description VARCHAR(2000) NOT NULL,
  status TEXT NOT NULL DEFAULT 'open',
  admin_notes VARCHAR(2000) NULL,
  reviewed_by BIGINT NULL,
  reviewed_at TIMESTAMPTZ NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT fk_reports_reporter FOREIGN KEY (reporter_id) REFERENCES users (id) ON DELETE CASCADE,
  CONSTRAINT fk_reports_ad FOREIGN KEY (advertisement_id) REFERENCES advertisements (id) ON DELETE SET NULL,
  CONSTRAINT fk_reports_seller FOREIGN KEY (seller_id) REFERENCES users (id) ON DELETE SET NULL,
  CONSTRAINT fk_reports_reviewer FOREIGN KEY (reviewed_by) REFERENCES users (id) ON DELETE SET NULL,
  CONSTRAINT fk_reports_conversation FOREIGN KEY (conversation_id) REFERENCES conversations (id) ON DELETE SET NULL,
  CONSTRAINT fk_reports_message FOREIGN KEY (message_id) REFERENCES messages (id) ON DELETE SET NULL,
  CONSTRAINT chk_reports_category CHECK (category IN ('fraud', 'fake_seller', 'misleading_description', 'incorrect_price', 'duplicate', 'suspicious_activity', 'inappropriate_content', 'message_abuse', 'other')),
  CONSTRAINT chk_reports_status CHECK (status IN ('open', 'investigating', 'resolved', 'dismissed'))
);
CREATE INDEX IF NOT EXISTS idx_reports_status_date ON reports (status, created_at);
CREATE INDEX IF NOT EXISTS idx_reports_reporter_date ON reports (reporter_id, created_at);
CREATE INDEX IF NOT EXISTS idx_reports_ad ON reports (advertisement_id);
CREATE INDEX IF NOT EXISTS idx_reports_conversation ON reports (conversation_id);
CREATE INDEX IF NOT EXISTS idx_reports_message ON reports (message_id);

CREATE TABLE IF NOT EXISTS payment_transactions (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id BIGINT NOT NULL,
  advertisement_id BIGINT NULL,
  payment_type TEXT NOT NULL,
  amount NUMERIC(13, 2) NOT NULL,
  currency CHAR(3) NOT NULL DEFAULT 'NGN',
  status TEXT NOT NULL DEFAULT 'pending',
  provider VARCHAR(80) NOT NULL,
  provider_reference VARCHAR(191) NOT NULL,
  provider_checkout_id VARCHAR(100) NULL,
  provider_payment_id VARCHAR(100) NULL,
  provider_session_expires_at TIMESTAMPTZ NULL,
  verified_at TIMESTAMPTZ NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT uq_payment_provider_reference UNIQUE (provider, provider_reference),
  CONSTRAINT uq_payment_provider_checkout UNIQUE (provider, provider_checkout_id),
  CONSTRAINT fk_payment_user FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE RESTRICT,
  CONSTRAINT fk_payment_ad FOREIGN KEY (advertisement_id) REFERENCES advertisements (id) ON DELETE SET NULL,
  CONSTRAINT chk_payment_amount CHECK (amount >= 0),
  CONSTRAINT chk_payment_type CHECK (payment_type IN ('featured_ad', 'promotion', 'other')),
  CONSTRAINT chk_payment_status CHECK (status IN ('pending', 'succeeded', 'failed')),
  CONSTRAINT chk_verified_payment CHECK (status <> 'succeeded' OR verified_at IS NOT NULL)
);
CREATE INDEX IF NOT EXISTS idx_payment_status_date ON payment_transactions (status, created_at);
CREATE INDEX IF NOT EXISTS idx_payment_user_date ON payment_transactions (user_id, created_at);

CREATE TABLE IF NOT EXISTS bachs_webhook_events (
  event_id VARCHAR(191) PRIMARY KEY,
  event_type VARCHAR(80) NOT NULL,
  received_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS idx_bachs_webhook_received ON bachs_webhook_events (received_at);

CREATE TABLE IF NOT EXISTS promotion_packages (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name CITEXT NOT NULL,
  description VARCHAR(1000) NOT NULL DEFAULT '',
  price NUMERIC(13, 2) NOT NULL,
  duration_days SMALLINT NOT NULL,
  benefits TEXT NULL,
  is_active BOOLEAN NOT NULL DEFAULT TRUE,
  created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT uq_promotion_packages_name UNIQUE (name),
  CONSTRAINT chk_promotion_package_price CHECK (price > 0),
  CONSTRAINT chk_promotion_package_duration CHECK (duration_days > 0)
);
CREATE INDEX IF NOT EXISTS idx_promotion_packages_active ON promotion_packages (is_active, duration_days);

CREATE TABLE IF NOT EXISTS promotions (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id BIGINT NOT NULL,
  advertisement_id BIGINT NULL,
  package_id BIGINT NOT NULL,
  payment_id BIGINT NOT NULL,
  duration_days SMALLINT NOT NULL,
  status TEXT NOT NULL DEFAULT 'pending_payment',
  starts_at TIMESTAMPTZ NULL,
  expires_at TIMESTAMPTZ NULL,
  impressions BIGINT NOT NULL DEFAULT 0,
  clicks BIGINT NOT NULL DEFAULT 0,
  created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT uq_promotion_payment UNIQUE (payment_id),
  CONSTRAINT fk_promotion_user FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE RESTRICT,
  CONSTRAINT fk_promotion_ad FOREIGN KEY (advertisement_id) REFERENCES advertisements (id) ON DELETE SET NULL,
  CONSTRAINT fk_promotion_package FOREIGN KEY (package_id) REFERENCES promotion_packages (id) ON DELETE RESTRICT,
  CONSTRAINT fk_promotion_payment FOREIGN KEY (payment_id) REFERENCES payment_transactions (id) ON DELETE RESTRICT,
  CONSTRAINT chk_promotion_duration CHECK (duration_days > 0),
  CONSTRAINT chk_promotion_status CHECK (status IN ('pending_payment', 'pending_approval', 'active', 'expired', 'paused', 'terminated', 'failed')),
  CONSTRAINT chk_promotion_dates CHECK (starts_at IS NULL OR expires_at IS NULL OR expires_at > starts_at)
);
CREATE INDEX IF NOT EXISTS idx_promotions_ad_status_expiry ON promotions (advertisement_id, status, expires_at);
CREATE INDEX IF NOT EXISTS idx_promotions_user_created ON promotions (user_id, created_at);
CREATE INDEX IF NOT EXISTS idx_promotions_status_expiry ON promotions (status, expires_at);

CREATE TABLE IF NOT EXISTS category_subcategories (
  category_id BIGINT NOT NULL,
  subcategory_id BIGINT NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (category_id, subcategory_id),
  CONSTRAINT uq_category_subcategory UNIQUE (subcategory_id),
  CONSTRAINT fk_category_subcategories_parent FOREIGN KEY (category_id) REFERENCES categories (id) ON DELETE CASCADE,
  CONSTRAINT fk_category_subcategories_child FOREIGN KEY (subcategory_id) REFERENCES categories (id) ON DELETE CASCADE,
  CONSTRAINT chk_category_not_own_parent CHECK (category_id <> subcategory_id)
);

CREATE TABLE IF NOT EXISTS seller_ratings (
  seller_id BIGINT NOT NULL,
  reviewer_id BIGINT NOT NULL,
  score SMALLINT NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (seller_id, reviewer_id),
  CONSTRAINT fk_rating_seller FOREIGN KEY (seller_id) REFERENCES users (id) ON DELETE CASCADE,
  CONSTRAINT fk_rating_reviewer FOREIGN KEY (reviewer_id) REFERENCES users (id) ON DELETE CASCADE,
  CONSTRAINT chk_rating_score CHECK (score BETWEEN 1 AND 5)
);

-- Keep updated_at current on every UPDATE (MySQL's ON UPDATE CURRENT_TIMESTAMP).
DO $$
DECLARE t TEXT;
BEGIN
  FOREACH t IN ARRAY ARRAY[
    'users', 'advertisements', 'wishlist_preferences', 'conversations', 'conversation_participants',
    'seller_profiles', 'seller_verifications', 'reports', 'payment_transactions',
    'promotion_packages', 'promotions', 'seller_ratings'
  ] LOOP
    EXECUTE format('DROP TRIGGER IF EXISTS trg_%1$s_updated_at ON %1$I', t);
    EXECUTE format('CREATE TRIGGER trg_%1$s_updated_at BEFORE UPDATE ON %1$I FOR EACH ROW EXECUTE FUNCTION set_updated_at()', t);
  END LOOP;
END $$;
